-- Finance pre-close evidence and deterministic monthly periods.
create table if not exists public.buildpulse_close_snapshots(id uuid primary key default gen_random_uuid(),period_id uuid not null references public.buildpulse_accounting_periods(id),entity_id uuid not null references public.buildpulse_accounting_entities(id),snapshot_kind text not null default 'preclose',status text not null default 'ready',base_currency text not null,trial_balance jsonb not null,totals jsonb not null,blockers jsonb not null default '[]'::jsonb,evidence_as_of timestamptz not null default now(),created_at timestamptz not null default now(),unique(period_id,snapshot_kind,evidence_as_of));
alter table public.buildpulse_close_snapshots enable row level security;revoke all on table public.buildpulse_close_snapshots from public,anon,authenticated;grant select,insert on table public.buildpulse_close_snapshots to service_role;
create or replace function public.buildpulse_ensure_monthly_accounting_periods(p_year integer) returns integer language plpgsql security definer set search_path=public as $$ declare e public.buildpulse_accounting_entities%rowtype;m integer;n integer:=0;s date;t date;begin if p_year<2020 or p_year>extract(year from current_date)::integer+1 then raise exception 'year_out_of_range';end if;select * into e from public.buildpulse_accounting_entities where is_default=true;if not found then raise exception 'default_entity_missing';end if;for m in 1..12 loop s:=make_date(p_year,m,1);t:=(s+interval '1 month - 1 day')::date;insert into public.buildpulse_accounting_periods(entity_id,period_start,period_end,status) values(e.id,s,t,'open') on conflict(entity_id,period_start,period_end) do nothing;if found then n:=n+1;end if;end loop;return n;end $$;
revoke all on function public.buildpulse_ensure_monthly_accounting_periods(integer) from public,anon,authenticated;grant execute on function public.buildpulse_ensure_monthly_accounting_periods(integer) to service_role;
create or replace function public.buildpulse_create_preclose_snapshot(p_period_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare p public.buildpulse_accounting_periods%rowtype;e public.buildpulse_accounting_entities%rowtype;tb jsonb;debits numeric(20,6);credits numeric(20,6);recon integer;foreign_paid integer;unresolved_tax integer;crypto_tax integer;bid uuid;begin select * into p from public.buildpulse_accounting_periods where id=p_period_id;if not found then return null;end if;select * into e from public.buildpulse_accounting_entities where id=p.entity_id;select count(*) into recon from public.buildpulse_finance_reconciliation_queue where reconciliation_state<>'ok' and paid_at::date between p.period_start and p.period_end;select count(*) into foreign_paid from public.buildpulse_accounting_documents where entity_id=p.entity_id and status='paid' and upper(currency)<>upper(e.base_currency) and paid_at::date between p.period_start and p.period_end;select count(*) into unresolved_tax from public.buildpulse_accounting_documents where entity_id=p.entity_id and status='paid' and paid_at::date between p.period_start and p.period_end and (immutable_snapshot->'automatic_tax'->>'enabled' is null or immutable_snapshot->'automatic_tax'->>'enabled'<>'true');select count(*) into crypto_tax from public.buildpulse_crypto_accounting_evidence where tax_status='pending_determination' and created_at::date between p.period_start and p.period_end;if recon+foreign_paid+unresolved_tax+crypto_tax>0 then raise exception 'preclose_blocked';end if;select coalesce(sum(l.debit),0),coalesce(sum(l.credit),0) into debits,credits from public.buildpulse_journal_entries j join public.buildpulse_journal_lines l on l.entry_id=j.id where j.entity_id=p.entity_id and j.status='posted' and j.entry_date between p.period_start and p.period_end;if abs(debits-credits)>0.000001 then raise exception 'unbalanced_period';end if;select coalesce(jsonb_agg(jsonb_build_object('account_code',account_code,'debit',debit,'credit',credit,'balance',debit-credit) order by account_code),'[]'::jsonb) into tb from (select l.account_code,round(sum(l.debit),6) debit,round(sum(l.credit),6) credit from public.buildpulse_journal_entries j join public.buildpulse_journal_lines l on l.entry_id=j.id where j.entity_id=p.entity_id and j.status='posted' and j.entry_date between p.period_start and p.period_end group by l.account_code)x;insert into public.buildpulse_close_snapshots(period_id,entity_id,base_currency,trial_balance,totals,blockers) values(p.id,p.entity_id,upper(e.base_currency),tb,jsonb_build_object('debits',debits,'credits',credits,'difference',debits-credits),'[]'::jsonb) returning id into bid;return bid;end $$;
revoke all on function public.buildpulse_create_preclose_snapshot(uuid) from public,anon,authenticated;grant execute on function public.buildpulse_create_preclose_snapshot(uuid) to service_role;